export const modules=[
{code:'SaaS',id:'MOD-A',name:'SaaS administration, identity and billing',milestone:'M1–M2',owner:'W01 + W03',purpose:'One organization, identity and entitlement model for agents, offices and product assets. Staff administration uses a separate control-plane context.',requirements:[
'Provision an organization through a durable job: seed built-in roles, six configurable pipeline stages, default lead source and business profile; expose pending/ready/failed state. Invitations use a hashed, expiring, one-use token and require the signed-in verified email to match the invitation.',
'Support owner, organization manager, agent, marketing editor, billing administrator and read-only analyst role presets. Permission codes come from the API catalog; scope is own/team/organization. Custom roles cannot grant rights the caller cannot delegate. Lock the organization row during owner changes and reject removal or demotion of its final active owner.',
'Offer organization, office, member and business-profile management with optimistic versions, audit events and visible entitlement limits. An identity may belong to multiple organizations; the active organization selector changes all data, cache and job contexts together.',
'Show account subscription, enabled/pending/disabled capabilities, invoices, annual invoice total and monthly equivalent separately. Preview plan changes, cancellation/resumption, proration, currency, taxes and effective date; require an unexpired preview and explicit acceptance before a financial operation.',
'Stripe webhook reconciliation determines billing state; application entitlements remain explicit records. Duplicate or out-of-order events trigger a current provider-state read, not timestamp-only entitlement changes. Failed provisioning never becomes ready merely because payment succeeded.',
'Super administrators see organization health, provisioning jobs, feature configuration, subscription reconciliation, redacted audit logs and operational summaries. Access to customer records requires a time-bound, reasoned grant and visible staff-session banner; it is not an ordinary tenant role.'
],entities:'organization, user_identity, role_definition, membership, member_invitation, office, office_member, business_profile, plan, subscription, entitlement, billing_change, invoice_reference, staff_principal, support_access_grant, audit_event',dependencies:'Verified OIDC identity; transactional database; jobs/outbox; design system; Stripe sandbox at M2.',permissions:'org.read/manage, members.read/manage, roles.read/write, offices.read/write, profiles.read/write, billing.read/manage, audit.read; platform.* only on staff control-plane routes.',ui:'Organization switcher; onboarding checklist; member/role tables; permission/scope editor; plan comparison and change preview; billing status panel; staff organization and job consoles.',integrations:'Entra External ID proposed default; Stripe hosted flows. Exact identity tenant, provider quotas and merchant setup are deployment inputs, not assumed available.',acceptance:[
'Given a member of organizations A and B, selecting A never returns B leads, jobs, exports, assets or notifications; a fabricated organization ID returns 404/403 with no data.',
'Two concurrent requests to remove the last owners cannot leave an organization without one. Invitation replay, expired token and wrong verified email all fail.',
'Repeated subscription confirmation creates one operation; a stale preview or changed entitlement version fails. A failed provider provision remains pending/failed with actionable support context.',
'A staff user without a valid scoped grant cannot read tenant CRM data. Expired/revoked grants fail on API and worker boundaries.'
],tests:'Unit permission-delegation and billing-preview rules; PostgreSQL RLS and owner-race integration tests; signed Stripe webhook replay/order tests; E2E invite, organization switch and billing sandbox preview.'},
{code:'Dashboard',id:'MOD-B',name:'Agent workspace, activity and appointments',milestone:'M2',owner:'W02 + W03',purpose:'A daily work surface that reports actual lead, task and integration state rather than unverified productivity narratives.',requirements:[
'Render assigned lead activity, overdue/today/upcoming tasks, appointments, pipeline summary, notifications and website/campaign health. Default scope is the current agent; permitted team/organization views are explicit selectors.',
'Every KPI includes definition/version, period, timezone, numerator/denominator where relevant, source and refresh time. Loading, empty, unavailable and ineligible states remain distinct; zero is a valid measured value.',
'Actions open an existing lead/task in a drawer with a shareable route. Quick actions use the same authorization and validation as full pages. Preferences affect layout only, not data-access scope.',
'Appointments reflect verified scheduling/cancellation events. The platform initially integrates a scheduling provider; it does not infer that a booking iframe synchronizes with CRM. Display organization and user timezone labels when they differ.',
'Notifications are member-owned and can be read without altering the underlying lead. Poll job/notification status initially; add server-sent events only after traffic measurements justify the extra connection lifecycle.'
],entities:'task, activity_event, appointment, notification, lead, metric_definition, metric_snapshot, integration_job',dependencies:'CRM queries; permissions; analytics definitions; calendar adapter; accessible shared shell.',permissions:'dashboard.read, self.notifications.read/write, appointments.read; dashboard aggregations apply the same row scope as source records.',ui:'KPI cards; source/freshness details; daily agenda; task drawer; activity list; integration health ribbon; notification center.',integrations:'Calendar/Calendly adapter behind integration_connection; job/status API. Provider account and webhook privileges verified at M4.',acceptance:[
'An empty account shows onboarding and empty states without fabricated engagement or hours-saved values.',
'Dashboard totals reconcile with the same scoped CRM/report query for the same time window; expired integrations display unavailable rather than zero.',
'Task completion updates the task and emits one activity/audit event; a unauthorized quick action fails identically to its full-page equivalent.',
'A booking cancellation delivered twice leaves one cancelled appointment, with UTC storage and correct America/Los_Angeles daylight-saving display.'
],tests:'Unit metric state and timezone presentation; scoped aggregation integration tests; E2E daily agenda, notification ownership and provider-degraded dashboard.'},
{code:'CRM',id:'MOD-D',name:'CRM, leads, deals, tasks and routing',milestone:'M2',owner:'W04',purpose:'Own the commercial relationship model independently of IDX or a white-label CRM provider.',requirements:[
'Separate contact identity/channels from a lead opportunity and a deal. Maintain normalized email/phone values, source attribution, optional user-provided intent/timeline, tags, stage history, notes and a communication/activity timeline. Unknown values remain unknown.',
'Provide saved list filters, server pagination, column preferences, bulk selection scope, lead detail drawers and a pipeline view. Default stages are Uncontacted, Attempted Contact, Nurturing, Dead, Under Contract and Closed; organizations can configure their own immutable stage IDs.',
'Routing precedence defaults to first-touch owner, listing-attributed agent, geography, then weighted round robin. Evaluate only active eligible members; serialize distribution state, record the winning rule and fall back to an unassigned queue when no recipient is eligible. Office and tenant boundaries apply to every rule.',
'Score documented engagement signals using a versioned deterministic formula before introducing AI. Show reason codes and last event time; score is sales follow-up prioritization, never housing eligibility, protected-attribute inference or mortgage approval.',
'CSV imports require a scoped signed upload, mapping, preview, row errors, duplicate candidates and an explicit reviewed merge/skip policy. Commit the accepted snapshot with an idempotency key; do not merge automatically across organizations or solely because a household shares a phone.',
'Exports run as jobs with source-scope authorization at request and download, short-lived artifact access, spreadsheet-formula neutralization and audit. Archiving a contact/lead cancels eligible pending sends and marks public organizer relationships according to the retention plan.',
'Tasks require assignee, title, due instant and IANA timezone. Stage, owner and note changes use If-Match or expected version, preserve historical events and return conflict instead of silently overwriting another agent.'
],entities:'contact, contact_channel, lead, lead_source, pipeline_stage, stage_transition, deal, task, note, tag, lead_tag, routing_rule, activity_event, import_job, consent_event, suppression',dependencies:'Tenant membership/role scope; jobs; input normalization; property inquiries; media uploads; events.',permissions:'crm.contacts/leads/tasks/deals/pipeline/tags/sources.read/write, crm.routing.read/manage, crm.import, data.export. Agent scope is assigned records; organization manager preset scope is organization; custom team scope is explicitly permitted offices; owner scope is organization.',ui:'Lead table + saved filters; contact drawer; history and notes; task editor; pipeline board with keyboard move alternative; assignment explanation; CSV preview; export job screen.',integrations:'Native inbound lead contract; property inquiry/form endpoints; optional signed external lead connectors. No reliance on unlicensed IDXHome control-panel APIs.',acceptance:[
'A captured inquiry retries twice but creates one submission/event and one deduplicated lead decision with source provenance.',
'A listing agent in another organization cannot become owner. Disabled members and round-robin race conditions are handled without lost or cross-office assignments.',
'A stale lead/task update returns 412; the existing event history remains intact. Archived leads do not receive new marketing enrollments.',
'Import preview/commit yields deterministic counts and cannot commit changed input under the same preview. Formula-like export cells are safe to open in a spreadsheet.',
'Contact merging preserves consent provenance and reports conflicting grants/withdrawals; withdrawal wins until a later valid grant is verified.'
],tests:'Unit normalization, deduplication, scoring and routing; concurrent round-robin/stage/RLS integration tests; adversarial import/export tests; E2E capture→assignment→task→pipeline.'},
{code:'CMS',id:'MOD-C',name:'Real estate website builder, content, domains and forms',milestone:'M3',owner:'W05 + W02',purpose:'Deliver a unified premium builder with independently owned templates and a versioned property-aware block schema.',requirements:[
'Use Puck as an editor component behind an adapter; retain platform-owned block documents, schemas and renderer. Ship independently designed agent, brokerage and landing template families. Template definitions are versioned repository assets; tenant customizations become content revisions.',
'Allow page, blog, landing, community, agent and testimonial documents with navigation, slug, SEO title/description, canonical path, social image and noindex settings. Offer hero, text, image, CTA, agent, testimonials, community, listing grid, search, form, map and footer blocks.',
'Save drafts as immutable revisions with optimistic document versions. Publish validates every block, image right, link, form and MLS capability, then atomically updates the revision pointer and emits cache invalidation. Preview and production have distinct hostnames and signed preview access; rollback republishes an existing compatible revision.',
'Unknown/older blocks preserve their data and render a safe editor warning; they cannot be silently dropped or published until migrated. Arbitrary scripts, SQL, unsafe HTML, remote fetch URLs and free-form executable custom CSS are excluded from the initial block contract.',
'Custom domains require ownership verification, a globally unique normalized hostname, TLS provisioning and exact host→site→organization mapping. A verification job never grants a hostname based on an unverified client claim. Detach revokes routing and certificates before the domain can be reassigned.',
'Media uploads are signed, tenant-prefixed, capped and MIME-sniffed, scanned before publication, transformed into responsive derivatives and attached to a rights attestation. Originals remain private unless explicitly permitted; SVG uploads are rejected or sanitized by a vetted pipeline, not embedded as executable user HTML.',
'Versioned form schemas define labels, required fields, bounds, select choices, honeypot/challenge, purpose-specific consent and confirmation. Server validation uses the published version. A durable transaction stores the entry, lead decision and outbox event before acknowledging. Ordinary form entry permits paste and accessible validation.',
'Initial forms do not offer public file uploads or pricing/payment fields. The API upload grant is staff-authenticated; public visitor file uploads require a later quota, scanning and abuse review. These are deferred from the reference Gravity Forms library rather than accidentally promised.',
'Public rendering is server-produced and SEO-friendly. Property blocks use approved public listing projections; a provider supporting only embeds cannot be presented as native searchable feed data. Hidden/deleted/expired listings invalidate page, map, image and alert caches.'
],entities:'site, site_domain, content_document, content_revision, media_asset, form_schema, form_entry, business_profile; versioned template registry in packages/templates',dependencies:'Design system; identity and entitlements; blob/CDN; DNS/TLS provider; contact capture; mock MLS capability layer from M1.',permissions:'sites.read/write, content.read/write/publish, domains.read/manage, media.read/write, forms.read/write. Publication is separate from draft editing; public routes resolve a verified published site.',ui:'Site cards; template picker; three-panel editor (blocks/layers, canvas, properties); breakpoint preview; draft/save/publish status; revision list; domain wizard; media library; form designer and submission summary.',integrations:'Puck MIT editor, object store and image pipeline; host/DNS/TLS adapters. Native CMS is the default; WordPress migration is a separate import adapter, not a required runtime dependency.',acceptance:[
'An editor can save a draft without publishing. Two editors changing the same document receive a conflict rather than losing content; rollback reproduces the selected published revision.',
'A malicious block/link/media URL or executable HTML is rejected; unsupported blocks remain recoverable. The public page cannot access another tenant’s media or draft revision.',
'Two organizations cannot claim the same hostname, including case/IDN-normalized variants. A spoofed Host header or unverified domain cannot select customer data.',
'A form retry records one lead decision and one consent evidence set. An unrecognized field, invalid published version, malicious size or unavailable commit returns a defined error without false success.',
'Published pages include correct canonical/robots/Open Graph and permitted listing attribution, with tested 360/768/1440px layout and keyboard block editing.'
],tests:'Block-schema/render snapshots, migration and sanitization unit tests; revision/domain uniqueness and capture transaction integration tests; signed-upload/scan tests; E2E draft→preview→publish→rollback and form capture.'},
{code:'Marketing',id:'MOD-E',name:'Marketing, campaigns, consent and automation',milestone:'M4',owner:'W06',purpose:'Own marketing policy and durable execution; use transport providers and a mature email editor without delegating the CRM source of truth.',requirements:[
'Support reusable email/SMS designs, broadcast segment previews, send-later, drip campaigns, birthday/transaction-anniversary greetings and enrollment tables. Email design uses Unlayer when licensed; design JSON and rendered HTML are versioned together through EmailEditorAdapter.',
'Workflow nodes are wait/email/SMS/condition/task; graphs contain at most 100 nodes, one entry and no cycles. Conditions use an allowlisted lead-filter/event DSL, not arbitrary code. Preview runs on a deterministic virtual clock and identifies required channel/entitlement prerequisites.',
'Triggers include captured lead, property inquiry, saved search, favorite, stage change and anniversary. Enrollment policies are once, after completion, or after configured inactivity. Published versions are immutable; edits affect future enrollments unless an explicit migration/cancellation is approved.',
'Store scheduled actions durably in PostgreSQL. BullMQ/Redis dispatches wake-ups, not the only copy of a schedule. Workers acquire bounded leases, validate tenant scope, version, entitlement, contact archive state, consent, suppression, sender verification and quiet hours immediately before provider submission.',
'Email uses a proposed Resend adapter; SMS uses a proposed Twilio adapter with registration/opt-in gates. Development uses a no-delivery transport. Sender domain/number readiness is a real state, not inferred from a campaign active flag. Vendor callbacks determine submitted/delivered/bounced/failed; opens are explicitly non-guaranteed engagement signals.',
'Idempotency covers native actions and provider request keys, but provider guarantees are capability-specific and time-limited. A timed-out send with uncertain acceptance becomes unknown; reconcile with the provider before resubmission. Never promise universal exactly-once delivery.',
'Opt-outs produce a suppression/withdrawal event before further marketing work is eligible. Cancelled enrollments invalidate pending generation keys; already accepted provider sends may be unretractable and must be shown accurately. Replies and STOP-like events follow the approved provider/consent policy.',
'Quiet hours use the recipient’s known IANA timezone or an organization fallback with visible policy. For calendar schedules, choose the first valid instant after a spring gap and the earlier occurrence in a fall overlap; record the choice and execute once. Anniversary schedules define leap-day behavior explicitly.'
],entities:'campaign, campaign_version, campaign_step, message_design, automation_rule, enrollment, scheduled_action, delivery_attempt, consent_event, suppression, webhook_inbox, outbox, integration_connection',dependencies:'Contacts, source/activity events, clock abstraction, recipient scopes, provider secrets, queue recovery, signed webhooks.',permissions:'campaigns.read/write/publish/enroll/send, automations.read/write, consent.write. Marketing editors can design without sending; send entitlement and permission are checked separately.',ui:'Campaign library; versioned workflow canvas plus accessible ordered list; email designer; SMS preview and length/merge checks; enrollment timeline; audience eligibility preview; sender health; delivery/unknown-state console.',integrations:'Unlayer licensing; Resend email API; Twilio SMS; optional calendar. Provider procurement, sender registration, quotas and current idempotency windows are M4 prerequisites.',acceptance:[
'A worker crash, duplicate event or Redis loss does not lose the PostgreSQL schedule. Recovery does not create duplicate native action keys.',
'Withdrawal between audience preview and execution blocks the send. Disabled texting, missing consent or suspended entitlement never displays a successful delivery.',
'Unknown provider acceptance cannot enter the normal blind-retry path. Duplicate/out-of-order receipts do not regress delivered to submitted.',
'Virtual-clock tests cover wait delays, cancel/restart generations, quiet hours, leap-day handling and both daylight-saving transitions.',
'Publishing a graph with cycles, missing designs, invalid merge fields or inaccessible segments fails with node-specific errors.'
],tests:'Unit rule graph, merge/consent and clock tests; outbox/lease/idempotency/unknown-acceptance integration tests; provider webhook fixtures; E2E sandbox-only preview→confirm→status→opt-out.'},
{code:'IDX',id:'MOD-F',name:'Property search, organizer and Las Vegas MLS',milestone:'M1 contract; M5 mock; M6 live gate',owner:'W07',purpose:'A provider-neutral property experience with feed rights, capability and freshness policies present from the first data model.',requirements:[
'Implement the MlsAdapter contract with a mock provider first. Each feed declares replication, live query, embedding, incremental/deletion and media-caching capabilities. Native ingestion is used only where authorized; proxy-only and embed-only providers have explicit feature limits.',
'Normalize provider/board/source listing keys, source status, price/currency, address, coordinates, property type, bedrooms/baths, area units, public remarks, media, attribution, modification time and display restrictions. Preserve source fields needed for mapping internally; never expose raw agent/private fields.',
'Provide list/map search, location/bounding-box filters, price/type/bed/bath filters, safe keywords, pagination, stable sorting, details and a property inquiry. Map and list use the same filtered result definition; hidden addresses also hide exact coordinates according to the approved policy.',
'Saved properties/searches are owned by a site-bound verified visitor. Listing changes generate deduplicated alert matches; before notification, recheck feed permission, listing availability, alert preference and consent. Inquiry capture routes through the native CRM with source and listing provenance.',
'Incremental synchronization follows opaque provider paging/cursors, handles identical timestamps and overlap, upserts idempotently and advances a checkpoint only after durable processing. Deleted/withdrawn data disappears promptly through listing state, caches, search indexes and scheduled alerts. Missing deletion support requires contract-approved reconciliation.',
'DisplayPolicy governs field/status visibility, attribution, refresh/freshness, retention, cache, images and AI use. Unknown contract rights default to disabled; independent regional adapters do not share tenant/feed data without explicit licensed authorization.',
'The project owner selected CoreLogic Trestle (now Cotality Trestle) as the provider on 10 October 2026. Target its documented RESO WebAPI adapter; approved Las Vegas connection details and credentials arrive at M6. Confirm the actual board, feed product, participant permissions, endpoint, accessible metadata and display/retention/media rights then; public documentation does not establish account authorization.',
'Every mock record/page/map result and exported sample is marked SYNTHETIC DEMO DATA. The production live-feed configuration rejects mock connections and synthetic records; mock listing changes can only drive no-delivery transport in development/staging.'
],entities:'mls_feed, listing, listing_media, mls_sync_run, mls_checkpoint, visitor_identity, saved_search, favorite, listing_alert_match, contact, lead, form_entry',dependencies:'M1 adapter/policy contracts; PostGIS; normalized filter schema; tenant/scope guard; Redis/CDN invalidation; no-delivery alert transport.',permissions:'mls.feeds.read/write, mls.read/sync for authorized tenant feed operators; published.site for sanitized public search; visitor.own for organizer records. Live-feed activation additionally requires recorded owner/provider approval.',ui:'Map/list search; filter chips/drawer; listing photo/details; attribution and freshness footer; saved search/preferences; inquiry form; feed-health and last-checkpoint console; visible synthetic banner.',integrations:'Owner-selected Trestle RESO WebAPI; public documentation verified, authorized Las Vegas connection remains M6. Provider-neutral ports preserve future regional support. MapLibre renderer with contracted tile/geocoding service; no production load against public demo tile servers.',acceptance:[
'The same application search contract works with mock and a capability-compatible live adapter without changing CRM, builder or organizer primary keys.',
'The mock suite covers active→pending→off-market, deletion, address suppression, no media, partial pages, expired token, 429, equal timestamps and retry after crash.',
'A failed page leaves the checkpoint at its last successful boundary. Replayed pages do not duplicate listings, alert matches or inquiry leads.',
'Expired, disallowed or stale-beyond-policy records do not appear in list, map, details, images or outbound alerts. Hidden address fields are not leaked through SEO/JSON-LD or coordinates.',
'M6 cannot exit without source-field mapping, signed-off display policy, permitted media/cache behavior, partner acceptance evidence and live synchronization monitoring.'
],tests:'Adapter contract tests against mock fixtures; spatial/filter equivalence; checkpoint/withdrawal/cache integration tests; E2E sample search→inquiry→CRM and organizer ownership; approved provider tests only at M6.'},
{code:'Reporting',id:'MOD-G',name:'Reporting, attribution and product analytics',milestone:'M2 basics; M7 advanced',owner:'W08',purpose:'Make platform outcomes auditable and comparable with published definitions rather than blended undocumented scorecards.',requirements:[
'Define website session/page engagement, captured/qualified leads, contact rate, stage conversion, campaign submitted/delivered/bounced/clicked activity, pipeline value and listing engagement. Separate counts, unique entities, cohorts and estimates.',
'Metric definitions are versioned JSON contracts with event source, numerator, denominator, exclusion rules, deduplication, timezone and freshness. Initial aggregates live in PostgreSQL; introduce a warehouse/search service only after measured query/retention limits.',
'Campaign conversion joins eligible events to a documented attribution window and reports unattributed records. Email opens may be affected by privacy proxies; never equate opens with confirmed human reading or business conversion.',
'Reporting filters and exports respect underlying agent/team/organization permissions. Raw form/chat payloads and full contact records do not enter anonymous traffic telemetry. Respect approved analytics consent and collection configuration.',
'Display data source, last refresh and unavailable status. Provider metrics retain their original source/window; publisher coverage is reported separately from actual search visibility or AI assistant answers.',
'Provide period comparisons, funnel and pipeline views, campaign/listing drill-down and account operational health. Initial reports are bounded synchronous queries; heavy exports become scoped durable jobs.'
],entities:'activity_event, metric_definition, metric_snapshot, lead, stage_transition, deal, delivery_attempt, listing, audit_event',dependencies:'Versioned event envelope; event ingestion/deduplication; tenant query scope; timezone; privacy/retention policy.',permissions:'reports.read and data.export; organization-level reports require scope beyond agent-owned records. Operational telemetry is not a customer analytics API.',ui:'Date/timezone selector; KPI definition drawer; trends/funnel tables and charts; cohort comparison; source/freshness labels; export job history.',integrations:'First-party events + approved provider aggregates; OpenTelemetry operational traces. Use one lightweight chart package, selected after accessibility/bundle evaluation, not the reference Plotly bundle by default.',acceptance:[
'A deterministic event fixture produces documented KPI numerator and denominator; duplicate and late events produce stable corrected aggregates.',
'Report row data and totals cannot exceed a caller’s CRM scope. Day boundaries and comparisons match the selected IANA timezone.',
'Unknown/missing provider statistics display unavailable and cannot be averaged into a synthetic success score.',
'An exported report includes metric version, scope, timezone, source period and last refresh; changing a definition preserves old report provenance.'
],tests:'Golden event/metric tests; scoped aggregation and late-event integration tests; E2E reconciliation against CRM and campaign views.'},
{code:'AI',id:'MOD-H',name:'Assistive AI and competitive intelligence',milestone:'M7',owner:'W09',purpose:'Assist people with drafting and understanding verified facts; AI is never a substitute for permission, licensed data rights or publication approval.',requirements:[
'Provide optional page/blog drafts, property descriptions, campaign drafts, lead activity summaries, workflow suggestions and analytics explanations. Each job records purpose, requester, context references, prompt/model configuration version, usage, warnings and expiry.',
'Use a server-side OpenAI Responses API adapter with schema-constrained outputs and a configured model selected through evaluation. Do not hard-code a marketing model name as a permanent default. Handle refusal, incomplete output, timeout and schema-invalid results without applying a partial result.',
'Retrieve only tenant-scoped, permission-filtered facts, with an explicit MLS AI-use flag where listing data is involved. Distinguish source facts from generated prose; citations point to verified fields/documents and cannot be fabricated by accepting model-provided IDs blindly.',
'Acceptance of a draft checks the destination write permission and expected revision, then saves a draft/version through the domain service. It never publishes, sends a campaign, changes consent, modifies a billing plan or acts on a lead merely because an AI job succeeded.',
'Lead qualification assistance summarizes voluntarily supplied intent/timeline and interaction history. It must not infer protected characteristics, decide access to housing/credit, or score financial eligibility. Humans review follow-up recommendations.',
'A conversational public-site assistant is a separate later opt-in capability: public published content and permitted listings only, no CRM/customer retrieval. Begin with read-only FAQ/property answers, citations and handoff; property inquiries use the standard consent-aware form, not a hidden AI side effect.',
'Analytics explanations include actual metric definitions and computed values; the model does not calculate financial/KPI truth from prose. A provider-neutral guard prevents arbitrary URL fetching, unapproved tool use and cross-tenant retrieval induced by listing or user prompt injection.',
'Require per-organization cost/request caps, bounded context/output, redacted telemetry, configurable retention and an approved provider data agreement. store:false reduces response persistence where supported but is not a promise of zero provider retention.'
],entities:'ai_job, content_revision, message_design, activity_event, metric_snapshot, listing (only approved public projection); context references rather than duplicated unrestricted customer data',dependencies:'Domain read/write permissions; approved data policy; prompt registry; provider/model configuration; evaluation fixtures; cost accounting.',permissions:'ai.use plus source permissions; ai.accept plus destination draft-write permission. Public assistant uses no staff session or private organization access.',ui:'Draft assistant panel with sources/diff/warnings; accept-as-draft/discard; job history; usage cap status; feedback and human handoff.',integrations:'OpenAI Responses API proposed initial adapter. Project access, retention controls, models and prices are checked at M7; no API key is requested for this document.',acceptance:[
'A generated claim absent from source facts is rejected or flagged by the evaluation workflow; source IDs must exist and be readable by the requester.',
'A malicious property description cannot cause a tool call, another tenant’s retrieval or an autonomous write/send.',
'A cancelled/refused/incomplete job leaves source records unchanged. Accepting a result fails if the destination version or permission changed.',
'Evaluation sets cover factuality, protected-attribute/eligibility requests, PII disclosure, prompt injection, useful abstention, schema compliance, cost and latency.',
'No AI feature is enabled in production until its evaluation thresholds, data rights, provider retention and user-review flow are accepted.'
],tests:'Provider mock/refusal/schema/cap tests; tenant retrieval and destination-version integration tests; offline evaluations; E2E draft→review→save-as-draft only.'},
{code:'Local',id:'MOD-I',name:'Local presence, brand assets and optional creative services',milestone:'M7 extension',owner:'W10',purpose:'Match local visibility capabilities through approved network providers while reporting honest source metrics. Creative print design is evaluated as an optional product.',requirements:[
'Maintain a canonical business profile for identity, contact, hours, categories, media and social links. A Yext adapter is the proposed first network provider; integration rights and API scope require procurement verification.',
'Profile changes create versioned synchronization jobs with validation, provider errors, retry/reconciliation and last-success indicators. Publisher listing health and duplicate/review references are distinct data domains.',
'Report publisher sync coverage, reviews/reputation and source-specific visibility metrics with definitions. Any real query-based AI visibility tracking is a separate explicit measurement feature, not renamed directory coverage.',
'Google Business connection, social scheduling and review-response workflows remain capability/permission gated. AI-assisted review responses are drafts that require human approval and a provider-supported publication method.',
'Reusable brand kits and email/page templates are launch features. Standalone print fulfillment, design packs, mortgage-specific products and advanced creative editors are deferred until product demand, licensing and fulfillment behavior are verified.'
],entities:'business_profile, business_entity, publisher_listing, review_reference, media_asset, integration_connection, integration_job, ai_job',dependencies:'Business/brand data; provider secret adapter; jobs/outbox; metric definitions; optional approved AI drafts.',permissions:'local.read/manage; ai.accept does not grant review publication; media rights and provider entitlements apply independently.',ui:'Profile completeness checklist; publisher status table; sync-job details; source-based analytics; optional brand/template library.',integrations:'Yext and Google Business where approved; creative/print provider undecided. Source audit Design Studio editor and advanced local workflows were not fully inspected.',acceptance:[
'A provider failure leaves a visible pending/failed job and never silently rewrites the business profile on an ordinary page view.',
'Publisher coverage cannot be labeled as actual AI answer visibility. Unavailable/gated review metrics remain outside any numeric denominator.',
'A drafted review response cannot be submitted without a permitted human publication action and provider capability.'
],tests:'Provider capability, profile normalization and metric definition unit tests; sync/reconciliation integration fixtures; E2E no-write view and human-reviewed draft.'},
{code:'Support',id:'MOD-J',name:'Support, integration operations and account health',milestone:'M2 basics; ongoing',owner:'W03 + W10 + W11',purpose:'Make provisioning and provider problems visible, recoverable and supportable without invisible staff access.',requirements:[
'Create/read scoped support tickets with subject, category and detailed description; maintain a ticket-event timeline with actor and status. Attachments are deferred until the upload/retention pipeline supports them.',
'Expose customer-safe integration status and jobs: queued/running/succeeded/failed/unknown, attempts, last success, safe error code and recommended action. Never display secrets, provider raw payloads or another organization’s support record.',
'Provide staff dashboards for failed provisioning, billing/feed reconciliation, sender eligibility, expired domains and worker lag. Replay is an explicit audited domain action with idempotency and scope validation, not a generic rerun-any-payload button.',
'Document onboarding and contextual help. Replace reference achievement/help clutter with task-relevant learning; do not assume a tutorial link means the named service is integrated.'
],entities:'ticket, ticket_event, integration_connection, integration_job, webhook_inbox, audit_event, support_access_grant',dependencies:'Staff/tenant authorization; observability; durable jobs; safe-error taxonomy; event audit.',permissions:'support.read/write, jobs.read, integrations.read/write/manage; scoped platform.* permissions for operational actions only.',ui:'Support inbox; ticket form/timeline; provider health cards; job detail/retry eligibility; onboarding/help panel; staff runbook links.',integrations:'Native support initially; optional external helpdesk adapter later. Available CRM connectors from the reference are feature candidates, not required active integrations.',acceptance:[
'A customer cannot retrieve another tenant’s ticket or raw provider error. A staff action records actor, grant, purpose, affected resource and trace ID.',
'Replay of a completed idempotent job cannot duplicate customer state or sends; unknown provider acceptance requires reconciliation before any retry.',
'Onboarding accurately distinguishes unconfigured, pending authorization, ready and degraded integrations.'
],tests:'Ticket scope and safe-error tests; replay/idempotency integration tests; E2E customer ticket and expiring staff-support access.'}
];

modules.push({code:'PWA',id:'MOD-K',name:'Full web application and installable iPhone/Android experience',milestone:'M1 foundation; M2–M7 workflow parity; M8 device gate',owner:'W12 + W02 + W11',purpose:'Deliver the same complete web application through browsers and home-screen installation on iPhone and Android, without App Store or Google Play distribution.',requirements:[
'Implement an HTTPS Progressive Web App using Next.js manifest support, an original icon set, display:standalone, stable manifest id, start URL, app scope and service worker. The workspace remains usable in ordinary browsers without installation. No native wrapper or app-store submission is part of the architecture.',
'Provide platform-appropriate installation guidance: iPhone browser share/menu Add to Home Screen and Android Install/Add to Home Screen. Detect install capability and standalone mode; never show a nonfunctional universal install button or block use behind installation.',
'Make every entitled workflow usable at 360px and larger: CRM capture/edit/tasks, dashboards, builder draft/preview/publish, campaign edit/preview/confirm, property search/inquiry/organizer, reports, settings and authorized administration. Complex canvases have accessible list/form alternatives; do not require a desktop to complete core commands.',
'Respect device safe areas, dynamic viewport height, orientation, virtual keyboards, touch targets, screen readers and system text enlargement. Preserve deep links and navigation history; reauthenticate safely after suspension, external OIDC and hosted billing flows.',
'Cache only approved static application assets and a generic offline screen. Initial release is online-first: no private CRM, session tokens, personalized HTML/RSC, messages, exports, AI results or MLS data in service-worker caches or IndexedDB. Offline mutations are visibly disabled and never reported as saved.',
'Preserve unsaved changes in current tab memory during brief connection loss and warn before navigation/update; process eviction may discard them. After reconnection refetch versions and permissions. Durable offline editing/synchronization is deferred to a separately reviewed data-conflict/security design.',
'Use versioned static asset caches and a waiting-worker update notice. Never force reload while a draft is dirty or a payment/publish/send confirmation is in flight. Reload only after user acceptance or a safe idle transition, and remove obsolete non-sensitive caches.',
'Offer opt-in standards-based Web Push for assigned-lead, task-due and job-failure notices where supported; the in-app inbox remains authoritative. Check capabilities and user gesture, handle denied permission, and keep lock-screen text generic with no contact/property details.',
'Store encrypted, tenant/member-scoped push subscriptions and revoke devices on explicit removal/logout and membership revocation. Validate HTTPS push endpoints against approved provider egress policy; reject local/private hosts. VAPID private keys are server secrets; push clicks open allowlisted same-origin deep links and recheck authorization.',
'M8 requires physical iPhone Safari/browser and installed-home-screen tests, plus Android Chrome/browser and installed tests. Cover sign-in, organization switching, all core workflows, interruptions/offline, SW upgrades, denied push, device removal, keyboard/safe-area behavior and no sensitive persistent caching.'
],entities:'push_subscription, notification, membership; versioned manifest/static assets; no private offline database in the initial release',dependencies:'Next.js app shell, device-aware shared UI, authenticated API, safe asset cache rules, notification events and no-delivery Web Push mock.',permissions:'Same module permissions in browser and installed mode; self.push.read/write owns device subscriptions; no permission is granted by installing the app.',ui:'Install guidance panel, standalone shell, mobile bottom navigation, full-screen drawers, online/offline state, update-ready notice, notification/device settings, accessible alternatives to complex canvases.',integrations:'Browser Web App Manifest, Service Worker, Push/Notifications APIs and server Web Push transport. OS/browser support is detected; no app-store accounts or native packaging required.',acceptance:[
'The application installs and launches standalone on a physical iPhone and Android device without an app-store listing; all entitled core commands have usable mobile paths.',
'An interrupted request never displays saved/completed without durable server acknowledgment; reconnection resolves idempotency and stale revisions safely.',
'After viewing contacts, billing, AI and listing details, CacheStorage/IndexedDB contain no sensitive API or personalized page data; logout/account switch cannot expose earlier user data offline.',
'A waiting service-worker update does not discard dirty editor content or duplicate a submitted command. Browser-tab use works when installation or push is unavailable.',
'Revoked/expired devices receive no new customer notices; lock-screen payloads and routes reveal no contact details and cannot bypass authentication.'
],tests:'Unit cache-allowlist/install/update rules; push ownership and egress integration tests; browser E2E offline/reconnect/version tests; mandatory physical iPhone/Android browser and installed-mode acceptance.'});

